#include <stdio.h>

int main(void) {
    int cargo[4] = {12, 7, 30, 5};
    int total = 0;
    for (int i = 0; i < 4; i++) {
        total += cargo[i];
    }
    printf("First: %d\n", cargo[0]);
    printf("Last: %d\n", cargo[3]);
    printf("Total: %d\n", total);
    return 0;
}

