#include <stdio.h>

int main(void) {
    char ship[] = "KERNEL";
    printf("%s\n", ship);
    printf("First letter: %c\n", ship[0]);
    int len = 0;
    while (ship[len] != '\0') {
        len++;
    }
    printf("Length: %d\n", len);
    return 0;
}

